uint8_t alarm_acknowledge(uint16_t config_id) {
    for (uint16_t i = 0; _alarm_lookup[i].rec != NULL; i++) {
        if (_alarm_lookup[i].config_id == config_id) {
            alarm_record_t* r = _alarm_lookup[i].rec;
            if (r->state == 1) {   /* 仅 Active 可被确认 */
                r->state = 2;
                r->acknowledged_at = lv_tick_get();
                ALARM_TRACE("[config id=%u] acknowledged -> Acknowledged (t=%lu)", (unsigned)config_id, (unsigned long)r->acknowledged_at);
                return 1;
            }
            return 0;
        }
    }
    ALARM_TRACE("[config id=%u] acknowledge failed: not found", (unsigned)config_id);
    return 0;
}

