#define DATA_LOG_MAX_VARS 16

#ifndef TREND_TRACE_ENABLE
#define TREND_TRACE_ENABLE 0
#endif
#define TREND_TRACE(fmt, ...) do { \
    if (TREND_TRACE_ENABLE) printf("[trend] " fmt "\n", ##__VA_ARGS__); \
} while (0)

#define DATA_LOG_MAX_RECORDS 8

typedef struct {
    uint32_t timestamp_ms;
    float values[DATA_LOG_MAX_VARS];
    uint8_t var_count;
    uint8_t is_valid;
} data_log_sample_t;

static data_log_sample_t _logbuf_log1[8];
static volatile uint16_t _logwr_log1 = 0;
static volatile uint16_t _logcnt_log1 = 0;
static volatile uint8_t _logfull_log1 = 0;

void datalog_init_log1(void) {
    _logwr_log1 = 0;
    _logcnt_log1 = 0;
    _logfull_log1 = 0;
    memset(_logbuf_log1, 0, sizeof(_logbuf_log1));
}

void datalog_sample_log1(float* values, uint8_t count) {
    if (values == NULL || count == 0) return;   /* 无有效数据不入环形缓冲 */
    data_log_sample_t* s = &_logbuf_log1[_logwr_log1];
    s->timestamp_ms = lv_tick_get();
    s->var_count = (count > DATA_LOG_MAX_VARS) ? DATA_LOG_MAX_VARS : count;
    s->is_valid = 1;
    memcpy(s->values, values, s->var_count * sizeof(float));

    _logwr_log1++;
    if (_logwr_log1 >= 8) {
        _logwr_log1 = 0;
        if (!_logfull_log1) TREND_TRACE("log-%s ring filled (%d records) -> wrap modes", "log1", 8);
        _logfull_log1 = 1;
    }

    if (!_logfull_log1) _logcnt_log1++;
}

void datalog_export_csv_log1(void (*write_fn)(const char*)) {
    if (!write_fn) return;
    uint16_t total = _logfull_log1 ? 8 : _logcnt_log1;
    uint16_t start = _logfull_log1 ? _logwr_log1 : 0;
    char buf[128];
    write_fn("timestamp_ms");
    write_fn(",v0");   /* 未绑定变量名时按列序输出 */
    write_fn("\n");

    for (uint16_t i = 0; i < total; i++) {
        uint16_t idx = (uint16_t)((start + i) % 8);
        data_log_sample_t* s = &_logbuf_log1[idx];
        if (!s->is_valid) continue;
        snprintf(buf, sizeof(buf), "%lu", (unsigned long)s->timestamp_ms);
        write_fn(buf);
        for (uint8_t j = 0; j < s->var_count; j++) {
            snprintf(buf, sizeof(buf), ",%.3f", (double)s->values[j]);
            write_fn(buf);
        }
        write_fn("\n");
    }
}

